d = os.environ['RLM_SESSION_DIR']
path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

with open(path, 'r') as f:
    lines = f.readlines()

# Process each line as JSON
for i, line in enumerate(lines[-50:]):  # Check last 50 lines
    try:
        msg = json.loads(line)
        if 'toolCall' in msg:
            tool = msg['toolCall']
            if tool['name'] == 'ipython':
                code = tool['arguments']['code']
                if 'load()' in code or 'load(G' in code or 'Demo pair' in code:
                    print(f"Line {i} (ipython tool):")
                    print(code[:500])
        if 'content' in msg:
            for c in msg['content']:
                if c.get('type') == 'reasoning.text':
                    print(f"Reasoning at {i}: {c.get('text', '')[50:200]}")
    except:
        pass

# Check if action_request_demos was sent
print("\n=== Checking for demo requests ===")
for i, line in enumerate(lines):
    if 'request_demos' in line:
        print(f"Found at {i}: {line[:200]}")

